-- Open-flow board test (Basys2-250): the Block Memory wizard's module (#794, bram.vhd, generated by
-- core/blockram.js from msg.mem): a dual-port RAM of 4096 words of 9 bits, two rows of RAMB16_S9_S9 (the
-- address's top bit chooses the row), READ_FIRST. Port B reads the words one after the other (a word about
-- every 0.33 s); port A reads the word 0x800 away (in the other row) and writes the switches (and BTN1 as bit
-- 8) into it while BTN0 is held:
--   LD7-LD0  the two words' low 8 bits XORed, LD7 also by their bit 8 (every output bit read: no dangling pin
--            in ISE's DRC); at first the ramp of msg.mem, then 0, with the three words at 0x800
library IEEE;
use IEEE.STD_LOGIC_1164.ALL;
use IEEE.NUMERIC_STD.ALL;

entity top is
  port (clk : in  std_logic;
        btn : in  std_logic_vector(1 downto 0);
        sw  : in  std_logic_vector(7 downto 0);
        led : out std_logic_vector(7 downto 0));
end top;

architecture rtl of top is
  signal n : unsigned(25 downto 0) := (others => '0');
  signal word, other, din, zeros : std_logic_vector(8 downto 0);
  signal addr, far : std_logic_vector(11 downto 0);
begin
  process (clk) begin if rising_edge(clk) then n <= n + 1; end if; end process;
  -- (the words 0-63, then 0x800-0x803, over and over)
  addr <= n(25) & "00000" & std_logic_vector(n(24 downto 19));
  far <= not addr(11) & addr(10 downto 0);
  din <= btn(1) & sw;
  zeros <= (others => '0');
  u_ram : entity work.bram port map (clka => clk, wea => btn(0), addra => far, dina => din, douta => other,
                                     clkb => clk, web => '0', addrb => addr, dinb => zeros, doutb => word);
  led <= (word(7) xor word(8) xor other(7) xor other(8)) & (word(6 downto 0) xor other(6 downto 0));
end rtl;
